∀ {R : Type u_1} {M : Type u_2} [inst : CommRing R] [inst_1 : AddCommGroup M] [inst_2 : Module R M] {n : ℕ}
  (f : Fin n → Module.Dual R M) (v : Fin n → M),
  ((exteriorPower.alternatingMapToDual R M n) f) ((exteriorPower.ιMulti R n) v) = (Matrix.of fun i j => (f j) (v i)).det

∀ {M : Type u_7} [inst : AddCommGroup M] {ι : Type u_8} [inst_1 : DecidableEq ι] [inst_2 : Fintype ι] {A : Type u_9}
  [inst_3 : CommRing A] [inst_4 : Module A M],
  LinearMap.detAux = Trunc.lift (fun b => Matrix.detMonoidHom.comp ↑(LinearMap.toMatrixAlgEquiv b)) ⋯

∀ {R : Type u_1} [inst : CommRing R] {M : Type u_2} [inst_1 : AddCommGroup M] [inst_2 : Module R M] {ι : Type u_4}
  [inst_3 : Fintype ι] [Module.Free R M] [Module.Finite R M] (f : ι → M →ₗ[R] M),
  LinearMap.det (LinearMap.pi fun i => f i ∘ₗ LinearMap.proj i) = ∏ i, LinearMap.det (f i)

∀ {M : Type u_2} [inst : AddCommGroup M] {ι : Type u_4} [inst_1 : DecidableEq ι] [inst_2 : Fintype ι] {A : Type u_5}
  [inst_3 : CommRing A] [inst_4 : Module A M] (b : Module.Basis ι A M) (f : M →ₗ[A] M),
  (LinearMap.detAux (Trunc.mk b)) f = ((LinearMap.toMatrix b b) f).det
